# token overlap.
_CONSTRUCT_KEYWORDS = ('class', 'import', 'try', 'for')


def _word_tokens(code):
    """Generic word / single-char tokens (identifiers, numbers, punctuation)."""
    return re.findall(r'\w+|[^\s\w]', code)


def _token_names(code, predicate):
    """Python tokenizer based lexical categories with regex fallback."""
    try:
        return [t.string for t in tokenize.generate_tokens(io.StringIO(code).readline)
                if predicate(t)]
    except Exception:
        return []


