    return _token_names(
        code, lambda t: t.type == tokenize.NAME and t.string not in _KEYWORDS) \
        or [t for t in re.findall(r'[A-Za-z_][A-Za-z0-9_]*', code)
            if t not in _KEYWORDS]


def _keywords(code):
    return _token_names(
        code, lambda t: t.type == tokenize.NAME and t.string in _KEYWORDS)


def _operators(code):
    ops = _token_names(code, lambda t: t.type == tokenize.OP)
    return ops or re.findall(r'[^\s\w]', code)


def _string_literals(code):
    return _token_names(code, lambda t: t.type == tokenize.STRING)


def _number_literals(code):
    nums = _token_names(code, lambda t: t.type == tokenize.NUMBER)
    return nums or re.findall(r'\b\d+\.?\d*\b', code)


def _jaccard(a, b):
    sa, sb = set(a), set(b)
    if not sa and not sb:
        return 1.0
    if not sa or not sb:
        return 0.0
    return len(sa & sb) / len(sa | sb)


def _counter_cosine(a, b):
    ca, cb = Counter(a), Counter(b)
    if not ca and not cb:
        return 1.0
    if not ca or not cb:
        return 0.0
    dot = sum((ca & cb).values())
    na = sum(v * v for v in ca.values()) ** 0.5
    nb = sum(v * v for v in cb.values()) ** 0.5
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na * nb)


def _seq_ratio(a, b):
    if not a and not b:
        return 1.0
    if not a or not b:
        return 0.0
